# Parameterized test for the GET /pet/{petId} endpoint
@pytest.mark.parametrize("pet_id, expected_status_code, auth_type", [
    (10, 200, "api_key"),          # Valid ID with API key authentication -> Success
    (99999999, 404, "api_key"),   # Non-existent ID with API key authentication -> Pet not found
    ("invalid", 400, "api_key"),  # Invalid ID with API key authentication -> Invalid ID supplied
    (10, 200, "oauth"),           # Valid ID with OAuth authentication -> Success
    ("invalid", 400, "oauth"),    # Invalid ID with OAuth authentication -> Invalid ID supplied
    (99999999, 404, "oauth"),     # Non-existent ID with OAuth authentication -> Pet not found
])
def test_get_pet_by_id(api_base_url, headers_with_api_key, oauth_token, default_headers, pet_id, expected_status_code, auth_type):
    """
    Test GET /pet/{petId} endpoint with different IDs and authentication scenarios.
    """
    url = f"{api_base_url}/pet/{pet_id}"
    
    if auth_type == "api_key":
        headers = {**default_headers, **headers_with_api_key}
    elif auth_type == "oauth":
        headers = {**default_headers, "Authorization": f"Bearer {oauth_token}"}
    else:
        headers = default_headers

    response = requests.get(url, headers=headers)
    
    # Validate the response status code
    assert response.status_code == expected_status_code
    
    # Validate the response body schema for 200 status code
